                const aapaPreparation =
                    new AapaPreparationPage(page);

                await aapaPreparation.verifyLoaded();


                /*
                 * ========================================================
                 * STEP 7
                 * Capture all Main Info values atomically
                 *
                 * IMPORTANT:
                 * The form has already shown React re-render behavior.
                 * Read all values from one DOM snapshot.
                 * ========================================================
                 */

                const snapshot =
                    await aapaPreparation
                        .mainInfoBody
                        .evaluate((body) => {

                            const labels =
                                Array.from(
                                    body.querySelectorAll('label'),
                                );

                            const getField =
                                (prefix: string) => {

                                    const label =
                                        labels.find(
                                            item =>
                                                (
                                                    item.textContent ??
                                                    ''
                                                )
                                                    .replace(
                                                        /\s+/g,
                                                        ' ',
                                                    )
                                                    .trim()
                                                    .startsWith(prefix),
                                        );

                                    return label
                                        ?.parentElement ??
                                        null;
                                };


                            const urgencyField =
                                getField('Urgency');

                            const startDateField =
                                getField('Start Date');

                            const endDateField =
                                getField('End Date');


                            const urgency =
                                urgencyField
                                    ?.querySelector(
                                        'select',
                                    ) as
                                HTMLSelectElement |
                                null;


                            const startDate =
                                startDateField
                                    ?.querySelector(
                                        'input[type="date"]',
                                    ) as
                                HTMLInputElement |
                                null;


                            const endDate =
                                endDateField
                                    ?.querySelector(
                                        'input[type="date"]',
                                    ) as
                                HTMLInputElement |
                                null;


                            return {
                                urgencyExists:
                                    Boolean(urgency),

                                urgencyValue:
                                    urgency?.value ??
                                    null,

                                urgencyText:
                                    urgency
                                        ?.selectedOptions[0]
                                        ?.textContent
                                        ?.trim() ??
                                    null,

                                startDateExists:
                                    Boolean(startDate),

                                startDateValue:
                                    startDate?.value ??
                                    null,

                                endDateExists:
                                    Boolean(endDate),

                                endDateValue:
                                    endDate?.value ??
                                    null,
                            };
                        });


                /*
                 * ========================================================
                 * STEP 8
                 * Verify controls were discovered
                 * ========================================================
                 */

                expect(
                    snapshot.urgencyExists,
                    'Urgency should exist after fresh reopen',
                ).toBe(true);

                expect(
                    snapshot.startDateExists,
                    'Start Date should exist after fresh reopen',
                ).toBe(true);

