                await expect(
                    revisedCategoryLabel,
                ).toHaveCount(1);

                await expect(
                    revisedSubcategoryLabel,
                ).toHaveCount(1);


                const overviewMandatoryState =
                    await updateAapaContainer.evaluate(
                        container => {

                            const getField =
                                (title: string) => {

                                    const labels =
                                        Array.from(
                                            container.querySelectorAll(
                                                'label',
                                            ),
                                        ) as HTMLLabelElement[];

                                    const label =
                                        labels.find(
                                            item =>
                                                (
                                                    item.getAttribute(
                                                        'title',
                                                    ) ??
                                                    ''
                                                ) === title,
                                        );

                                    if (!label) {
                                        return {
                                            title,
                                            found: false,
                                            requiredIndicator: false,
                                            nativeRequired: null,
                                            value: null,
                                            controlType: null,
                                        };
                                    }

                                    const field =
                                        label.closest(
                                            '[data-uda-type]',
                                        );

                                    const input =
                                        field?.querySelector(
                                            'input',
                                        ) as
                                        HTMLInputElement |
                                        null;

                                    const combobox =
                                        field?.querySelector(
                                            '[role="combobox"]',
                                        ) as
                                        HTMLElement |
                                        null;

                                    const hiddenInput =
                                        field?.querySelector(
                                            'input[type="hidden"]',
                                        ) as
                                        HTMLInputElement |
                                        null;

                                    const requiredIndicator =
                                        Boolean(
                                            label.querySelector(
                                                '[aria-label="required"]',
                                            ),
                                        ) ||
                                        (
                                            label.textContent ??
                                            ''
                                        ).includes('*');

                                    return {
                                        title,
                                        found: true,

                                        requiredIndicator,

                                        udaType:
                                            field?.getAttribute(
                                                'data-uda-type',
                                            ) ?? null,

                                        udaName:
                                            field?.getAttribute(
                                                'data-uda-name',
                                            ) ?? null,

                                        controlType:
                                            combobox
                                                ? 'combobox'
                                                : input
                                                    ? input.type
                                                    : null,

                                        nativeRequired:
                                            hiddenInput
                                                ? hiddenInput.required
                                                : input
                                                    ? input.required
                                                    : null,

                                        value:
                                            hiddenInput
                                                ? hiddenInput.value
                                                : input
                                                    ? input.value
                                                    : null,

                                        displayText:
                                            combobox
                                                ? (
                                                    combobox.textContent ??
                                                    ''
                                                )
                                                    .replace(
                                                        /\s+/g,
                                                        ' ',
                                                    )
                                                    .trim()
                                                : null,
                                    };
                                };

                            return {
                                internalIncidentTitle:
                                    getField(
                                        'Internal Incident Title',
                                    ),

                                revisedCategory:
                                    getField(
                                        'Revised Category',
                                    ),

                                revisedSubcategory:
                                    getField(
                                        'Revised Subcategory',
                                    ),
                            };
                        },
                    );

                console.log('');
