                            if (!form) {
                                return {
                                    found: false,
                                    noValidate: null,
                                    valid: null,
                                    action: null,
                                    method: null,
                                };
                            }

                            return {
                                found: true,

                                noValidate:
                                    form.noValidate,

                                valid:
                                    form.checkValidity(),

                                action:
                                    form.getAttribute(
                                        'action',
                                    ),

                                method:
                                    form.getAttribute(
                                        'method',
                                    ),
                            };
