                                        window.getComputedStyle(
                                            html,
                                        );

                                    const rect =
                                        html.getBoundingClientRect();

                                    if (
                                        style.display === 'none' ||
                                        style.visibility === 'hidden' ||
                                        rect.width === 0 ||
                                        rect.height === 0
                                    ) {
                                        return false;
                                    }

