                console.log('========================================');
                console.log(
                    'Calculate Priority Enabled: true',
                );
                console.log(
                    `Expected Raw Score: ${expectedRawScore}`,
                );
                console.log('========================================');


                /*
                 * ========================================================
                 * STEP 18
                 * Verify matrix BEFORE calculation
                 * ========================================================
                 */

                const matrixBeforeCalculate =
                    await updateAapaContainer.evaluate(
                        container => {

                            const selected =
                                Array.from(
                                    container.querySelectorAll(
                                        '[role="checkbox"][aria-checked="true"]',
                                    ),
                                ).map(
                                    element => ({
                                        label:
                                            element.getAttribute(
                                                'aria-label',
                                            ),

                                        row:
                                            (
                                                element.closest('tr')
                                                    ?.textContent ?? ''
                                            )
                                                .replace(/\s+/g, ' ')
                                                .trim(),
                                    }),
                                );

                            return {
                                selectedCount:
                                    selected.length,

                                selected,
                            };
                        },
                    );

                expect(
                    matrixBeforeCalculate.selectedCount,
                ).toBe(12);

                expect(
                    matrixBeforeCalculate.selected.filter(
                        item => item.label === 'Low',
                    ),
                ).toHaveLength(4);

                expect(
                    matrixBeforeCalculate.selected.filter(
                        item => item.label === 'Medium',
                    ),
                ).toHaveLength(1);

                expect(
                    matrixBeforeCalculate.selected.filter(
                        item => item.label === 'High',
                    ),
                ).toHaveLength(2);

                expect(
                    matrixBeforeCalculate.selected.filter(
                        item => item.label === 'Critical',
                    ),
                ).toHaveLength(5);

                console.log('');
                console.log('========================================');
                console.log('MATRIX BEFORE FINAL CALCULATION');
